 async function action(fn){if(busy||!db||closed)return;busy=true;root.setAttribute('aria-busy','true');for(const id of ['vCreate','vLoad','vBuy','vSwitch','vImport','vExport','vPlaceHouse'])$(id).disabled=true;message('');try{await fn()}catch(e){message(e.message||'Speichern fehlgeschlagen.')}finally{busy=false;root.removeAttribute('aria-busy');for(const id of ['vCreate','vLoad','vSwitch','vImport','vExport'])$(id).disabled=false;if(s){recalc();if(draft)checkHouse()}}}
